/* Retrospective counts distinct seasons within one award category. */
(() => {
  const h=window.STEM_DATA.school_history;
  if(!h)return;
  const entities=new Map(h.entities.map(e=>[e.id,e]));
  const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const q=s=>document.querySelector(s);
  const kinds={school:"escuela",club:"club extraescolar",community:"club independiente",mixed:"varias escuelas / distrito",unresolved:"La conexión escolar no se conoce"};
  const levels={world_match:"victoria de los partidos · final mundial",world_skills:"1o lugar de la categoría técnica",world_judged:"premio valorado · evento mundial",world_division:"la victoria de la división",world_finalist:"finalista del premio mundial",world_podium:"lugar de premio · categoría mundial",national_match:"victoria nacional",national_skills:"el nacional Skills",national_other:"premio nacional",regional_match:"victoria del estado / región",regional_skills:"categoría técnica · región",school_internal:"torneo dentro de la escuela",regional_podium:"lugar del premio · región",regional_judged:"premio del estado / región",qualification:"calificación en el Mundial",network_match:"victoria de la red escolar · país",unresolved_stage:"premio · nivel de final aclarar",unclassified:"la categoría no está establecida"};
  const prov={organizer_protocol:"el protocolo del organizador",school_report:"informe de la escuela",school_operator_report:"el informe de la red escolar",season_partner_report:"el relato del compañero de temporada"};
  const status={complete:"conjunto completo de los premios seleccionados de la FRC",complete_selected:"7 primeros lugares seleccionados de la WRO",cancelled:"El campeonato se cancela",awards_only:"formato de premios sólo",pending:"Los resultados mundiales están por venir.",protocol:"el protocolo del ganador de la FLL",report:"mensaje del participante / socio",case:"resultados de selección",not_started:"La liga no existía.",archive_gap:"archivo / conexiones escolares no se han restaurado"};
  const f={window:10,league:'FRC',kind:'',level:'',query:'',entity:''};let init=false;
  const years=()=>Array.from({length:f.window},(_,i)=>2027-f.window+i);
  const rowYears=(id,level='world_match')=>new Set(h.results.filter(r=>r.entity_id===id&&r.league==='FRC'&&r.level===level&&r.year>=2027-f.window).map(r=>r.year));
  function leaderCards(){
    const full=e=>new Set(h.results.filter(r=>r.entity_id===e.id&&r.league==='FRC'&&r.level==='world_match').map(r=>r.year)).size;
    let a=h.entities.filter(e=>full(e)>1);
    a=a.filter(e=>(!f.kind||f.kind===e.kind)&&(!f.query||(e.name+' '+e.country).toLowerCase().includes(f.query.toLowerCase())));
    a.sort((a,b)=>rowYears(b.id).size-rowYears(a.id).size||full(b)-full(a)||a.name.localeCompare(b.name));
    if(!f.kind)a=a.filter(e=>e.kind==='school');
    q('#history-leaders').innerHTML=a.map(e=>`<button class="history-leader${f.entity===e.id?' chosen':''}" data-history-entity="${safe(e.id)}" aria-pressed="${f.entity===e.id}"><span>${safe(e.country)} · ${safe(kinds[e.kind])}</span><h4>${safe(e.name)}</h4><div class="history-leader-value"><strong>${rowYears(e.id).size}</strong><span>de las temporadas de victoria<br>por ${f.window} años</span></div><div class="history-dots" aria-label="Temporadas: ${[...rowYears(e.id)].join(', ')||"No hay un ganador de campeonato en esta ventana"}">${years().map(y=>`<i class="${rowYears(e.id).has(y)?'won':y===2020||y===2021?'no-final':''}" title="${y}: ${rowYears(e.id).has(y)?'Championship Winner':y===2020||y===2021?"no se disputó el Campeonato":"No hay ganador de campeonato en este juego"}"><span>${String(y).slice(2)}</span></i>`).join('')}</div><p>${e.kind==='school'?"equipo de adolescentes · para niños más tarde":"programa exterior · entrada separada de la escuela"}</p></button>`).join('')||"<p class=\"history-empty\">Para este tipo de búsqueda no hay ganadores de FRC Championship repetidos en el conjunto extraído.</p>";
  }
  function render(){
    if(!q('#school-history'))return;
    if(!init){
      const leagues=[...new Set(h.results.map(r=>r.league))].sort();
      q('#school-history').innerHTML=`<div class="history-heading"><div><p class="section-kicker">DIEZ AÑOS · VERIFICAMOS LOS RESULTADOS</p><h3>¿Quién es el ganador?<br><em>Una y otra vez.</em></h3><p>La historia del equipo, el campus y el nivel de la recompensa.</p></div><div class="history-period" role="group" aria-label="el período de la historia"><button data-history-window="10" aria-pressed="true">10 años</button><button data-history-window="5" aria-pressed="false">5 años</button><small id="history-window-label"></small></div></div>
        <div class="history-summary"><span><b>${h.results.length}</b> de los resultados</span><span><b>44</b> FRC winning-alliance entries</span><span><b>28</b> los primeros puestos de la WRO</span><span>Se ha comprobado <b>${safe(h.checked)}</b></span></div>
        <p class="history-intro">El liderazgo de muchos años es más fiable en FRC. Se han leído las alianzas ganadoras y las principales Chairman / Impact de los premios 11 de los juegos Championship en el 2017–2026. otras ligas y la relación de los ganadores con las escuelas se estudió parcialmente.</p>
        <div class="history-block-title"><h4>ganador de la FRC Championship repetido</h4><p>miembro de la alianza ganadora · equipos de adolescentes · diferentes temporadas</p></div><div id="history-leaders" class="history-leaders"></div><p class="history-small">punto de color — Championship Winner. punto de la — el final de partido cancelado; está vacía — No hay un premio así en el conjunto verificado. en el 2017–2019 Había dos individuos. Championship. No es una evaluación de todos los resultados de la escuela..</p>
        <div class="history-block-title"><h4>equipo → temporada → fuente primaria</h4><p>elige una escuela superior o filtra la tabla.</p></div><div class="history-filters"><label>Liga<select data-history-filter="league"><option value="">todos los resultados estudiados</option>${leagues.map(l=>`<option>${safe(l)}</option>`).join('')}</select></label><label>la organización<select data-history-filter="kind"><option value="">todos los tipos</option>${Object.entries(kinds).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>nivel de la recompensa<select data-history-filter="level"><option value="">todos los niveles por separado</option>${Object.entries(levels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Buscar<input data-history-filter="query" type="search" placeholder="Madera, Taiwan, Sprout…"></label></div><p id="history-result-count" role="status" aria-live="polite"></p><div class="history-selection" id="history-selection" hidden></div><div class="history-table-scroll" tabindex="0" aria-label="historia de resultados, tabla en rodaje"><table><caption class="sr-only">resultados y fuentes, filtros actuales</caption><thead><tr><th>año</th><th>escuela / organización</th><th>Resultado</th><th>Evidencia</th></tr></thead><tbody id="history-results"></tbody></table></div>
        <div class="history-block-title"><h4>¿qué años realmente se han comprobado?</h4><p>Un vacío en el archivo no significa una derrota o una falta de equipo.</p></div><div class="history-coverage-scroll" tabindex="0" aria-label="matriz de cobertura por años"><table class="history-coverage"><thead id="history-coverage-head"></thead><tbody id="history-coverage-body"></tbody></table></div><div class="history-legend"><span><i class="complete"></i> el conjunto completo elegido</span><span><i class="case"></i> Casos e informes</span><span><i class="pending"></i> los resultados futuros</span><span><i class="archive_gap"></i> hueco</span></div><div id="history-coverage-detail" class="history-coverage-detail"></div>
        <div class="history-block-title"><h4>¿Qué cambia para Matvey y Oscar?</h4><p>Edad 6 / 9, el futuro 10–12 y el equipo de adolescentes se comprueban por separado.</p></div><div id="history-family" class="history-family"></div><details class="school-method"><summary>Como se cuentan las estaciones y distinguen los títulos</summary><ul>${h.methodology.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></details><details class="school-method"><summary>que es lo que se necesita para una comparación global completa.</summary><ul>${h.gaps.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></details><div class="school-downloads"><a class="button primary" href="downloads/STEM_school_history.json" download>historia y fuentes · JSON</a><a class="button secondary" href="downloads/STEM_school_history.csv" download>todos los resultados · CSV</a><a class="button secondary" href="downloads/STEM_school_history.md" download>análisis · texto</a></div>`;
      q('#history-family').innerHTML=h.family_routes.map((r,i)=>`<article><span>0${i+1}</span><h4>${safe(r.name)}</h4><p>${safe(r.detail)}</p><div>${r.ids.map(id=>`<button data-school-open="${id}">${safe(window.STEM_DATA.schools.find(s=>s.id===id).name)} ↗</button>`).join('')}</div></article>`).join('');
      q('#history-coverage-detail').innerHTML=h.coverage.map(c=>`<details><summary>${safe(c.name)} · ${c.status==='bounded_complete'?"el conjunto completo elegido":"archivo parcial"}</summary><p>${safe(c.detail)}</p><div>${c.sources.map((u,i)=>`<a href="${safe(u)}" target="_blank" rel="noopener">fuente ${i+1} ↗</a>`).join('')}</div></details>`).join('');
      init=true;
    }
    q('#history-window-label').textContent=`${2027-f.window}–2026 · según ${safe(h.checked)}`;
    document.querySelectorAll('[data-history-window]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.historyWindow)===f.window)));
    q('#school-history').querySelectorAll('[data-history-filter]').forEach(x=>{if(x.value!==f[x.dataset.historyFilter])x.value=f[x.dataset.historyFilter];});
    leaderCards();
    const a=h.results.filter(r=>{const e=entities.get(r.entity_id);return r.year>=2027-f.window&&(!f.league||r.league===f.league)&&(!f.kind||e.kind===f.kind)&&(!f.level||r.level===f.level)&&(!f.entity||e.id===f.entity)&&(!f.query||JSON.stringify([e,r]).toLowerCase().includes(f.query.toLowerCase()));}).sort((a,b)=>b.year-a.year||entities.get(a.entity_id).name.localeCompare(entities.get(b.entity_id).name));
    q('#history-result-count').textContent=`Se muestran ${a.length} de ${h.results.filter(r=>r.year>=2027-f.window).length} registros en el periodo ${2027-f.window}2026. registro  premio del equipo, no número de escuelas o temporadas ganadoras.`;
    q('#history-selection').hidden=!f.entity;
    q('#history-selection').innerHTML=f.entity?`<strong>${safe(entities.get(f.entity).name)}</strong><button data-history-clear>quitar la opción ×</button>`:'';
    q('#history-results').innerHTML=a.map(r=>{const e=entities.get(r.entity_id);return `<tr><td>${r.year}</td><td><strong>${safe(e.name)}</strong><small>${safe(e.country)} · ${safe(kinds[e.kind])}</small><small>${safe(r.team)} ${r.team_id?'#'+safe(r.team_id):''}</small>${e.school_id?`<button data-school-open="${e.school_id}">archivo de la escuela</button>`:''}<details><summary>conexión con la escuela / edad</summary><p>${safe(e.note||"la escuela en particular se ha nombrado como fuente; la lengua, la selección y el lugar requieren una verificación.")}</p><p>${e.age==='primary'?"hay una escalera de la escuela primaria / Elementary track; especifique la edad del equipo en particular.":e.age==='unknown'?"No se ha establecido la edad de un equipo en particular.":"el resultado de los adolescentes; no prueba del equipo para el 6 / 9."}</p></details></td><td><span class="history-award-level ${r.level}">${safe(levels[r.level])}</span><strong>${safe(r.award)}</strong><small>${safe(r.league)} · ${safe(r.category)}</small><small>${safe(r.stage)}</small><details><summary>las matices del resultado</summary><p>${safe(r.note)}</p></details></td><td><span>${safe(prov[r.provenance]||r.provenance)}</span><a href="${safe(r.source)}" target="_blank" rel="noopener">verifique la fuente</a></td></tr>`;}).join('')||"<tr><td colspan=\"4\">No hay resultados para estos filtros en el archivo actual.</td></tr>";
    q('#history-coverage-head').innerHTML=`<tr><th>liga / programa</th>${years().map(y=>`<th>${y}</th>`).join('')}</tr>`;
    q('#history-coverage-body').innerHTML=h.coverage.map(c=>`<tr><th>${safe(c.name)}</th>${years().map(y=>`<td><span class="${c.years[y]}" tabindex="0" title="${safe(status[c.years[y]])}" aria-label="${safe(c.name)} ${y}: ${safe(status[c.years[y]])}">${['complete','complete_selected'].includes(c.years[y])?'✓':c.years[y]==='pending'?'◷':c.years[y]==='cancelled'||c.years[y]==='awards_only'?'∅':c.years[y]==='archive_gap'?'—':c.years[y]==='not_started'?'·':'●'}</span></td>`).join('')}</tr>`).join('');
  }
  document.addEventListener('click',ev=>{
    const b=ev.target.closest('button');if(!b)return;
    if(b.dataset.historyWindow){f.window=Number(b.dataset.historyWindow);render();}
    if(b.dataset.historyEntity){f.entity=f.entity===b.dataset.historyEntity?'':b.dataset.historyEntity;f.league='FRC';f.level='';render();q('#history-result-count').scrollIntoView({behavior:'smooth',block:'start'});}
    if(b.hasAttribute('data-history-clear')){f.entity='';render();}
  });
  document.addEventListener('change',ev=>{if(ev.target.dataset.historyFilter&&ev.target.dataset.historyFilter!=='query'){f[ev.target.dataset.historyFilter]=ev.target.value;f.entity='';render();}});
  document.addEventListener('input',ev=>{if(ev.target.dataset.historyFilter==='query'){f.query=ev.target.value;f.entity='';render();}});
  window.renderSchoolHistory=render;
})();
